using System;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Forms;
internal static class MemoryTests {
    static object Field(object target,string name){return target.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(target);}
    static void Pump(int ms){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(4);}}
    static long CachedBytes(PetAtlas atlas){return ((IDictionary)Field(atlas,"pngs")).Values.Cast<Bitmap>().Sum(b=>(long)b.Width*b.Height*4);}
    static object TokenProof(){string home=Path.Combine(Path.GetTempPath(),"HubTokenMemory-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(home,"sessions"));string path=Path.Combine(home,"sessions","usage.jsonl"),stamp=DateTime.UtcNow.ToString("o"),line="{\"timestamp\":\""+stamp+"\",\"type\":\"token_usage_record\",\"payload\":{\"response_id\":\"first\",\"usage\":{\"total_tokens\":100}}}";
        using(var output=new StreamWriter(path,false,new System.Text.UTF8Encoding(false))){for(int i=0;i<10000;i++)output.WriteLine("{\"type\":\"other\",\"data\":\""+new string('x',2048)+"\"}");output.WriteLine(line);output.WriteLine(line);output.Write(new string('x',1024*1024+1));output.WriteLine();output.WriteLine(line.Replace("first","second").Replace(":100",":200"));}
        double initial,appended;bool partial;using(var reader=new PetTokenReader(home)){var snapshot=reader.Read();initial=snapshot.Today;partial=snapshot.Loading;File.AppendAllText(path,line.Replace("first","third").Replace(":100",":300").Substring(0,100));reader.Read();File.AppendAllText(path,line.Replace("first","third").Replace(":100",":300").Substring(100)+"\n");appended=reader.Read().Today;}
        if(initial!=300||partial||appended!=600)throw new Exception("Streaming token scan lost counters, deduplication or partial lines");return new{fixtureBytes=new FileInfo(path).Length,initial,appended,onlyCountersRetained=true};}
    [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=args[0],report=args[1];bool strict=args.Length>2;long initial=Process.GetCurrentProcess().PrivateMemorySize64;var packs=PetPack.Discover(root,Path.Combine(Path.GetTempPath(),"HubMemory-"+Guid.NewGuid().ToString("N")));
        long atlasInitial,atlasAfter;int cached;using(var atlas=new PetAtlas(packs.First(p=>p.Id=="deepseek"))){atlasInitial=CachedBytes(atlas);using(var canvas=new Bitmap(192,208))using(var g=Graphics.FromImage(canvas)){for(int cycle=0;cycle<4;cycle++)for(int row=9;row<atlas.Rows;row++)atlas.Draw(g,new RectangleF(0,0,192,208),row,.4);}atlasAfter=CachedBytes(atlas);cached=((IDictionary)Field(atlas,"pngs")).Count;}
        bool loaded,hiddenReleased,restored,staticFrame,hiddenVisible;string visibility="";int thumbnailFrames=0;using(var form=new Form{ShowInTaskbar=false,Opacity=0,ClientSize=new Size(300,200)})using(var preview=new WallpaperPreview{Animate=false,Dock=DockStyle.Fill}){form.Controls.Add(preview);preview.VisibleChanged+=delegate{visibility+=preview.Visible+"/";};preview.SetMedia(Path.Combine(root,"wallpapers","dresden-moonlight.gif"));form.Show();Pump(350);loaded=preview.HasPicture;var picture=Field(preview,"picture") as Image;try{thumbnailFrames=picture.GetFrameCount(FrameDimension.Time);}catch(ArgumentException){thumbnailFrames=1;}staticFrame=thumbnailFrames==1;form.Hide();Pump(80);hiddenReleased=!preview.HasPicture;hiddenVisible=preview.Visible;form.Show();Pump(350);restored=preview.HasPicture;}
        var tokens=TokenProof();bool pass=atlasInitial<=4*1024*1024&&atlasAfter<=4*1024*1024&&cached<=8&&loaded&&staticFrame&&hiddenReleased&&restored;var result=new{pass=!strict||pass,optimized=pass,pngCacheAtStart=atlasInitial,pngCacheAfterAllActions=atlasAfter,pngCachedFiles=cached,staticThumbnailFrames=thumbnailFrames,thumbnailLoaded=loaded,hiddenPreviewReleased=hiddenReleased,hiddenVisible,visibility,visiblePreviewRestored=restored,tokens,initialPrivateBytes=initial,privateBytes=Process.GetCurrentProcess().PrivateMemorySize64,workingSetBytes=Process.GetCurrentProcess().WorkingSet64};File.WriteAllText(report,new JavaScriptSerializer().Serialize(result));return strict&&!pass?1:0;
    }catch(Exception e){File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new{pass=false,error=e.ToString()}));return 1;}}
}
